  // Removing a member unassigns every live issue assigned to them, one
  // issue.unassigned per issue; archived issues keep their assignee.
  it("unassigns live issues assigned to a removed member", async () => {
    const tenant = await createTenant("member-remove-unassign", "growth");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!target) throw new Error("fixture member missing");

    const liveIssue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Live and assigned",
        assigneeId: tenant.userIds.viewer,
      }),
    );
    const archivedIssue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Archived and assigned",
        assigneeId: tenant.userIds.viewer,
      }),
    );
    await issueService.archiveIssue(tenant.actors.owner, tenant.org.id, archivedIssue.id);

    const detachers: Unsubscribe[] = [];
    const unassigned = capture("issue.unassigned", detachers);

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
    });

    for (const off of detachers) off();

    expect(unassigned).toHaveLength(1);
    expect(unassigned[0]).toMatchObject({
      orgId: tenant.org.id,
      issueId: liveIssue.id,
      projectId: tenant.project.id,
      previousAssigneeId: tenant.userIds.viewer,
      actorId: tenant.actors.owner.userId,
    });

    const stillArchived = await issueService.getIssue(
      tenant.actors.owner,
      tenant.org.id,
      archivedIssue.id,
    );
    expect(stillArchived.issue.assigneeId).toBe(tenant.userIds.viewer);
  });
});

